/* Local reading progress, independent of quiz progress and study materials. */
window.ReadingProgress=(()=>{
 const KEY='illustrated-kjv-reading-v1';let data,names,navigate,saved={read:[],bookmark:null},read=new Set(),selected=null,current=null,storageOK=true;
 const $=id=>document.getElementById(id),key=(b,c,v)=>`${b}:${c}:${v}`;
 function valid(x){return x&&Number.isInteger(x.book)&&Number.isInteger(x.chapter)&&Number.isInteger(x.verse)&&!!data.books[x.book]?.chapters[x.chapter-1]?.[x.verse-1]}
 function persist(){saved.read=[...read];try{localStorage.setItem(KEY,JSON.stringify(saved))}catch{storageOK=false}status()}
 function reference(x){return `${names[x.book]} ${x.chapter}:${x.verse}`}
 function status(){const b=saved.bookmark;$('readingStatus').textContent=(b?`Bookmark: ${reference(b)}`:'Tap a verse, then bookmark it.')+(!storageOK?' · Browser storage unavailable; changes last only this visit.':'');$('resumeBookmark').disabled=!b;$('markUnread').disabled=!selected||!read.has(key(selected.book,selected.chapter,selected.verse))}
 function select(x,mark=true){selected=x;document.dispatchEvent(new CustomEvent("bible-verse-selected",{detail:x}));if(mark){read.add(key(x.book,x.chapter,x.verse));persist()}highlight();status()}
 function highlight(){document.querySelectorAll('#scripture .verse').forEach(el=>{const x={...current,verse:+el.dataset.verse};el.classList.toggle('selected-verse',!!selected&&key(x.book,x.chapter,x.verse)===key(selected.book,selected.chapter,selected.verse));el.classList.toggle('bookmarked-verse',!!saved.bookmark&&key(x.book,x.chapter,x.verse)===key(saved.bookmark.book,saved.bookmark.chapter,saved.bookmark.verse))})}
 function decorate(book,chapter){current={book,chapter};document.querySelectorAll('#scripture .verse').forEach(el=>{el.tabIndex=0;el.setAttribute('aria-label',`${names[book]} ${chapter}:${el.dataset.verse}`);el.onclick=()=>select({book,chapter,verse:+el.dataset.verse});el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}}});highlight();status()}
 function overview(){const total=data.books.reduce((s,b)=>s+b.chapters.reduce((t,c)=>t+c.length,0),0);$('readingTotals').textContent=`${read.size.toLocaleString()} of ${total.toLocaleString()} verses read · ${(total-read.size).toLocaleString()} remaining · ${(read.size/total*100).toFixed(1)}%`;$('readingMeter').max=total;$('readingMeter').value=read.size;const root=$('readingBooks');root.replaceChildren();data.books.forEach((book,b)=>{let count=0,totalBook=0;book.chapters.forEach((ch,ci)=>{totalBook+=ch.length;ch.forEach((_,vi)=>{if(read.has(key(b,ci+1,vi+1)))count++})});const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=`${names[b]} · ${count}/${totalBook} read`;details.append(summary);details.ontoggle=()=>{if(!details.open||details.children.length>1)return;book.chapters.forEach((verses,ci)=>{const chapter=document.createElement('details'),title=document.createElement('summary');const n=verses.filter((_,vi)=>read.has(key(b,ci+1,vi+1))).length;title.textContent=`Chapter ${ci+1} · ${n}/${verses.length} read`;chapter.append(title);chapter.ontoggle=()=>{if(!chapter.open||chapter.children.length>1)return;const grid=document.createElement('div');grid.className='progress-verses';verses.forEach((text,vi)=>{const btn=document.createElement('button'),x={book:b,chapter:ci+1,verse:vi+1},isRead=read.has(key(b,ci+1,vi+1));btn.type='button';btn.textContent=vi+1;btn.className=isRead?'read-verse':'';btn.title=`${reference(x)} · ${isRead?'Read':'Unread'} · ${text}`;btn.setAttribute('aria-label',btn.title);btn.onclick=()=>{select(x);$('readingModal').hidden=true;navigate(b,ci+1,vi+1)};grid.append(btn)});chapter.append(grid)};details.append(chapter)})};root.append(details)});$('readingModal').hidden=false;$('readingModal').querySelector('[data-close]').focus()}
 function init(d,n,go){data=d;names=n;navigate=go;try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&Array.isArray(raw.read)){saved.bookmark=valid(raw.bookmark)?raw.bookmark:null;read=new Set(raw.read.filter(k=>{if(typeof k!=='string')return false;const a=k.split(':').map(Number);return a.length===3&&valid({book:a[0],chapter:a[1],verse:a[2]})}))}}catch{storageOK=false}selected=saved.bookmark;$('bookmarkHere').onclick=()=>{const x=selected&&selected.book===current.book&&selected.chapter===current.chapter?selected:{...current,verse:1};saved.bookmark={...x};select(x,false);persist()};$('resumeBookmark').onclick=()=>{if(saved.bookmark){select({...saved.bookmark},false);navigate(selected.book,selected.chapter,selected.verse)}};$('markUnread').onclick=()=>{if(selected){read.delete(key(selected.book,selected.chapter,selected.verse));persist()}};$('readingOverview').onclick=overview;status()}
 return {init,decorate,bookmark:()=>saved.bookmark};
})();
